import crypto from "node:crypto";

const CODE_COUNT = 10;
const CODE_BYTES = 16;

function normalizeCode(code) {
  if (typeof code !== "string") return null;

  const normalized = code.trim().toUpperCase();

  // Accept only the exact format generated by this service.
  if (!/^([A-F0-9]{4}-){3}[A-F0-9]{4}$/.test(normalized)) {
    return null;
  }

  return normalized;
}

export function hashRecoveryCode(code) {
  const normalized = normalizeCode(code);

  if (!normalized) {
    return null;
  }

  return crypto.createHash("sha256").update(normalized, "utf8").digest("hex");
}

export function generateRecoveryCodes() {
  const codes = Array.from({ length: CODE_COUNT }, () => {
    const raw = crypto.randomBytes(CODE_BYTES).toString("hex").toUpperCase();

    return raw.match(/.{4}/g).join("-");
  });

  return {
    codes,
    hashes: codes.map((code) => hashRecoveryCode(code)),
  };
}

/**
 * Atomically consume one code.
 * The User schema must define mfa.recoveryCodeHashes as an array.
 */
export async function consumeRecoveryCode(User, userId, submittedCode) {
  const hash = hashRecoveryCode(submittedCode);

  if (!hash) {
    return false;
  }

  const result = await User.updateOne(
    {
      _id: userId,
      "mfa.twoFactorEnabled": true,
      "mfa.recoveryCodeHashes": hash,
    },
    {
      $pull: {
        "mfa.recoveryCodeHashes": hash,
      },
    }
  );

  return result.modifiedCount === 1;
}
